CREATE TABLE IF NOT EXISTS cards (id TEXT PRIMARY KEY, topic TEXT NOT NULL, q TEXT NOT NULL, a TEXT NOT NULL, source TEXT, created INTEGER NOT NULL, updated INTEGER NOT NULL, deleted INTEGER NOT NULL DEFAULT 0, s REAL, d REAL, last INTEGER, due INTEGER, reps INTEGER NOT NULL DEFAULT 0, lapses INTEGER NOT NULL DEFAULT 0);
CREATE INDEX IF NOT EXISTS cards_topic ON cards(topic);
CREATE INDEX IF NOT EXISTS cards_updated ON cards(updated);
CREATE TABLE IF NOT EXISTS reviews (id INTEGER PRIMARY KEY, card_id TEXT NOT NULL, ts INTEGER NOT NULL, grade INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS meta (k TEXT PRIMARY KEY, v TEXT NOT NULL);
